@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Outfit:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#07111e;--panel:#0b1928;--line:#172a3b;--muted:#73869a;--white:#edf5fb;--cyan:#57f3d0;--lime:#d2ff79;--mono:'DM Mono',monospace;--sans:'Outfit',sans-serif}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--white);font-family:var(--sans);-webkit-tap-highlight-color:transparent}body{min-height:100svh;background:radial-gradient(ellipse at 50% 35%,#102136 0%,#091522 54%,#060e19 100%);overflow-x:hidden}.game-shell{max-width:1180px;min-height:100svh;padding:20px 46px 14px;margin:0 auto;display:flex;flex-direction:column;position:relative}.game-shell:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.22;background-image:radial-gradient(#9ac1de 0.6px,transparent .6px);background-size:27px 27px;mask-image:linear-gradient(to bottom,transparent,#000 20%,#000 85%,transparent)}.topbar{height:48px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(123,162,190,.13);position:relative;z-index:1}.brand{display:flex;align-items:center;gap:11px;color:#eff8ff;text-decoration:none;font-size:14px;font-weight:800;letter-spacing:1.55px}.brand-light{color:#7c94a7;font-weight:500}.brand-mark{display:flex;align-items:flex-end;gap:2px;height:20px;transform:skew(-24deg)}.brand-mark i{display:block;width:4px;background:var(--cyan);border-radius:1px;box-shadow:0 0 9px #57f3d080}.brand-mark i:nth-child(1){height:8px}.brand-mark i:nth-child(2){height:14px}.brand-mark i:nth-child(3){height:20px}.top-meta,.best-label,.best-unit,.eyebrow,.arena-topline,.arena-bottomline,.score-caption,.score-foot,.card-note,.control-title,.control-hint,.mini-action small,footer,.cover-kicker,.cover-foot{font-family:var(--mono);letter-spacing:1.1px}.top-meta{font-size:9px;color:#8094a6;display:flex;align-items:center;gap:9px}.live-dot{height:6px;width:6px;border-radius:50%;background:#74f6ca;box-shadow:0 0 9px #74f6ca}.meta-divider{color:#385064}.icon-button{width:34px;height:34px;background:transparent;border:1px solid #203448;border-radius:9px;display:grid;place-items:center;color:#8aa1b3;cursor:pointer}.icon-button:hover{border-color:var(--cyan);color:var(--cyan)}.icon-button svg{width:17px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}.intro-row{display:flex;justify-content:space-between;align-items:flex-end;padding:26px 0 18px;position:relative;z-index:1}.eyebrow{font-size:9px;color:#849aae;display:flex;align-items:center;gap:9px}.eyebrow-line{height:1px;width:23px;background:var(--cyan);box-shadow:0 0 8px #57f3d088}h1{font-size:clamp(34px,4vw,47px);line-height:1;margin:7px 0 6px;font-weight:700;letter-spacing:-1.6px}h1 span{color:var(--cyan)}.subtitle{color:#8396a8;font-size:13px;margin:0;font-weight:400}.best-card{display:flex;align-items:baseline;gap:7px;padding-bottom:4px}.best-label{font-size:8px;color:#71869a;letter-spacing:1.2px;margin-right:8px}.best-card strong{font:500 22px var(--mono);color:#e8f4fc}.best-unit{font-size:8px;color:#52687b}.play-area{position:relative;display:grid;grid-template-columns:minmax(0,1fr) 205px;gap:16px;z-index:1}.arena-frame{min-width:0;background:linear-gradient(145deg,rgba(13,29,45,.96),rgba(8,21,34,.97));border:1px solid #203449;border-radius:13px;overflow:hidden;box-shadow:0 18px 55px #0004,inset 0 1px #ffffff08}.arena-topline,.arena-bottomline{height:37px;display:flex;align-items:center;justify-content:space-between;padding:0 17px;color:#72879a;font-size:8px;letter-spacing:1px}.arena-topline{border-bottom:1px solid #172b3b}.arena-topline>span:first-child{display:flex;align-items:center;gap:8px}.status-pip{width:6px;height:6px;border-radius:50%;background:#8c9cab;display:inline-block}.status-pip.running{background:var(--lime);box-shadow:0 0 8px var(--lime)}.status-pip.paused{background:#ffbc64;box-shadow:0 0 8px #ffbc64}.arena-hint b{color:#c6d6e0;font-weight:400}.canvas-wrap{position:relative;height:clamp(330px,37vw,423px);background:radial-gradient(ellipse at 50% 52%,#10253a 0%,#0b1c2d 48%,#091725 82%);overflow:hidden;touch-action:none}canvas{display:block;width:100%;height:100%;outline:none}.arena-bottomline{border-top:1px solid #172b3b;height:36px;justify-content:center;gap:24px}.arena-bottomline>span{display:flex;align-items:center;gap:7px}.keycap{font:11px var(--sans);color:var(--cyan)}.legend-block{width:8px;height:8px;background:#48e9c4;border-radius:2px;box-shadow:0 0 7px #48e9c480}.legend-orb{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 6px var(--lime)}.score-rail{display:flex;flex-direction:column;gap:11px}.score-card{background:linear-gradient(145deg,#102337,#0c1a29);border:1px solid #20364a;border-radius:12px;padding:17px 17px}.score-main{min-height:146px}.score-caption{font-size:9px;color:#8ba0b0;display:flex;justify-content:space-between;align-items:center}.score-spark{font-size:13px;color:var(--lime)}.score-value{font:500 54px/.98 var(--mono);letter-spacing:-3px;margin:12px 0 11px;color:#f2fbff;text-shadow:0 0 26px #57f3d01c}.score-foot{font-size:8px;color:#7790a3;display:flex;gap:7px;align-items:center;letter-spacing:.5px}.score-dot{width:5px;height:5px;border-radius:50%;background:#557084}.compact-card{padding:14px 17px 13px}.pace-row{display:flex;align-items:baseline;gap:4px;margin-top:8px}.pace-row strong{font:500 29px var(--mono);color:var(--cyan)}.pace-row>span{font:12px var(--mono);color:#7a94a5}.pace-meter{height:3px;background:#20384a;flex:1;margin-left:12px;align-self:center;border-radius:9px;overflow:hidden}.pace-meter i{display:block;width:18%;height:100%;background:linear-gradient(90deg,var(--cyan),var(--lime));transition:width .25s}.card-note{font-size:8px;letter-spacing:.3px;color:#657b8e;margin-top:8px}.tip-card{display:flex;gap:11px;padding:13px 13px;border:1px solid #20364a;border-radius:11px;background:#0b1a29;flex:1;align-items:flex-start}.tip-icon{width:25px;height:25px;flex:none;border-radius:7px;background:#153647;color:var(--cyan);display:grid;place-items:center;font-size:18px}.tip-card strong{font-size:11px;font-weight:600;color:#d9e8ef}.tip-card p{font-size:10px;line-height:1.45;color:#7890a1;margin:4px 0 0}.screen-cover{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;background:linear-gradient(90deg,rgba(7,17,30,.2),rgba(7,17,30,.68),rgba(7,17,30,.2));z-index:2;transition:opacity .25s,visibility .25s}.screen-cover.hidden{opacity:0;visibility:hidden;pointer-events:none}.cover-orbit{position:relative;width:55px;height:55px;border:1px solid #4be7c54d;border-radius:50%;display:grid;place-items:center;margin-bottom:10px;box-shadow:0 0 25px #49e8c51c,inset 0 0 18px #49e8c512}.cover-orbit:before,.cover-orbit:after{content:"";position:absolute;border:1px solid #52efd233;border-radius:50%;transform:rotate(-30deg)}.cover-orbit:before{width:74px;height:24px}.cover-orbit:after{width:90px;height:35px;transform:rotate(35deg)}.cover-gem{font-size:19px;color:var(--lime);text-shadow:0 0 13px var(--lime);transform:rotate(-45deg)}.cover-kicker{font-size:8px;color:#84adad;letter-spacing:1.8px;margin:0 0 6px}.screen-cover h2{font-size:clamp(25px,3vw,34px);line-height:1.02;letter-spacing:-.7px;margin:0;color:#eaf5fa}.screen-cover h2 span{color:var(--cyan)}.screen-cover p{font-size:11px;color:#8ba0af;margin:9px 0 15px}.primary-button{display:flex;align-items:center;justify-content:center;gap:24px;border:0;border-radius:7px;padding:0 14px 0 20px;height:39px;background:var(--lime);color:#12211b;font:600 10px var(--mono);letter-spacing:1.1px;cursor:pointer;box-shadow:0 5px 20px #cafa5942;transition:transform .15s,box-shadow .15s}.primary-button:hover{transform:translateY(-2px);box-shadow:0 8px 26px #cafa5960}.button-arrow{font:17px var(--sans)}.cover-foot{font-size:7px;color:#688093;margin-top:14px;letter-spacing:1px}.cover-foot i{font-style:normal;color:var(--cyan);padding:0 5px}.pause-badge{position:absolute;top:15px;right:15px;border:1px solid #f4ba67;border-radius:5px;padding:6px 9px;color:#ffd18d;background:#07111ed9;font:9px var(--mono);letter-spacing:1px;z-index:3}.mobile-controls{display:none}footer{display:flex;justify-content:space-between;align-items:center;margin-top:auto;padding-top:16px;color:#52697d;font-size:8px;letter-spacing:.8px}footer .footer-center{color:#7890a0}footer .footer-center span{color:#b4cad5}footer b{font-size:10px;color:var(--cyan);padding-left:4px}
