      ctx.save();ctx.globalAlpha=.32;ctx.strokeStyle='#c1fff0';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(px-a+5,py+b-lift+3);ctx.lineTo(px,py+TILE_H-lift-3);ctx.stroke();ctx.restore();
